package com.beeboee.magnot.region;
import com.beeboee.magnot.Magnot;import net.minecraft.core.BlockPos;import net.minecraft.nbt.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.saveddata.SavedData;import net.minecraft.world.phys.Vec3;import java.util.*;
public final class FerrousRegionSavedData extends SavedData{private static final String NAME=Magnot.MOD_ID+"_ferrous_regions";private final List<FerrousRegion> regions=new ArrayList<>();private transient FerrousRegionIndex index;public static FerrousRegionSavedData get(ServerLevel level){return level.getDataStorage().computeIfAbsent(FerrousRegionSavedData::load,FerrousRegionSavedData::new,NAME);}public static FerrousRegionSavedData load(CompoundTag tag){FerrousRegionSavedData d=new FerrousRegionSavedData();ListTag list=tag.getList("Regions",Tag.TAG_COMPOUND);for(int i=0;i<list.size();i++)d.regions.add(FerrousRegion.load(list.getCompound(i)));return d;}@Override public CompoundTag save(CompoundTag tag){ListTag list=new ListTag();for(FerrousRegion r:regions)list.add(r.save());tag.put("Regions",list);return tag;}public List<FerrousRegion> regions(){return List.copyOf(regions);}public void addRegion(FerrousRegion r){removeRegion(r.id());regions.add(r);changed();}public FerrousRegion addRegion(BlockPos a,BlockPos b){FerrousRegion r=FerrousRegion.fromCorners(a,b);addRegion(r);return r;}public boolean removeRegion(UUID id){boolean v=regions.removeIf(r->r.id().equals(id));if(v)changed();return v;}public Optional<FerrousRegion> removeIntersectingById(UUID id,Vec3 a,Vec3 b){for(int i=0;i<regions.size();i++){FerrousRegion r=regions.get(i);if(r.id().equals(id)&&r.intersectsSegment(a,b)){regions.remove(i);changed();return Optional.of(r);}}return Optional.empty();}public boolean containsPoint(Vec3 p){return index().contains(p);}public boolean blocksMagnet(Vec3 a,Vec3 b){return index().blocks(a,b);}private FerrousRegionIndex index(){if(index==null)index=FerrousRegionIndex.build(regions);return index;}private void changed(){index=null;FerrousMagnetRules.invalidateCaches();setDirty();}}
